<?php require __DIR__.'/inc/header.php';$title='Categories & Tags';$pdo=db();if(is_post()){verify_csrf();$a=(string)post('action');if($a==='term'){ $name=trim((string)post('name'));$type=(string)post('post_type','articles');$taxonomy=(string)post('taxonomy','category');if($name){$st=$pdo->prepare('INSERT OR IGNORE INTO terms(name,slug,taxonomy,post_type,description) VALUES(?,?,?,?,?)');$st->execute([$name,slugify($name.'-'.$type.'-'.$taxonomy),$taxonomy,$type,post('description','')]);flash('success','Term created.');} }elseif($a==='category'){ $name=trim((string)post('name'));$type=(string)post('type');if($name){$st=$pdo->prepare('INSERT OR IGNORE INTO categories(name,slug,type,description) VALUES(?,?,?,?)');$st->execute([$name,slugify($name),$type,post('description','')]);flash('success','Category created.');}}redirect('/admin/taxonomy.php');}$cats=$pdo->query('SELECT * FROM categories ORDER BY type,sort_order,name')->fetchAll();$terms=$pdo->query("SELECT * FROM terms ORDER BY post_type,taxonomy,name")->fetchAll();?><div class="grid xl:grid-cols-2 gap-6"><div class="bg-white border rounded-2xl p-5 soft"><div class="font-black text-lg">Create Category</div><form method="post" class="mt-4 space-y-3"><?=csrf_input()?><input type="hidden" name="action" value="category"><input name="name" required placeholder="Category name" class="w-full rounded-xl border-slate-200"><select name="type" class="w-full rounded-xl border-slate-200"><option>gadgets</option><option>jersey</option><option>fashion</option></select><textarea name="description" placeholder="Description" class="w-full rounded-xl border-slate-200"></textarea><button class="grad600 text-white px-4 py-3 rounded-xl font-bold">Add Category</button></form><div class="mt-6 divide-y"><?php foreach($cats as $c):?><div class="py-3 flex justify-between"><div><b><?=e($c['name'])?></b><div class="text-xs text-slate-400"><?=e($c['type'])?></div></div><span class="text-xs text-slate-400">#<?=$c['id']?></span></div><?php endforeach;?></div></div><div class="bg-white border rounded-2xl p-5 soft"><div class="font-black text-lg">Create Tag</div><form method="post" class="mt-4 space-y-3"><?=csrf_input()?><input type="hidden" name="action" value="term"><input name="name" required placeholder="Tag name" class="w-full rounded-xl border-slate-200"><select name="taxonomy" class="w-full rounded-xl border-slate-200"><option>tag</option><option>category</option></select><select name="post_type" class="w-full rounded-xl border-slate-200"><?php foreach(['gadgets','jersey','fashion','articles','docs','pages'] as $t):?><option><?=$t?></option><?php endforeach;?></select><button class="grad600b text-white px-4 py-3 rounded-xl font-bold">Add Term</button></form><div class="mt-6 grid grid-cols-2 gap-2"><?php foreach($terms as $t):?><div class="rounded-xl bg-slate-50 p-3"><div class="font-bold text-sm"><?=e($t['name'])?></div><div class="text-xs text-slate-400"><?=e($t['taxonomy'])?> · <?=e($t['post_type'])?></div></div><?php endforeach;?></div></div></div><?php require __DIR__.'/inc/footer.php'; ?>
